from pathlib import Path
files={}
files['src/components/manager/ManagerUI.jsx']=r'''import {useEffect,useId,useRef,useState} from 'react';
import {Link} from 'react-router-dom';
import {ArrowUpRight,Download,X} from 'lucide-react';
import {Card,CardContent} from '@/components/ui/card';
import {Button} from '@/components/ui/button';
import {Badge} from '@/components/ui/badge';
import {Input} from '@/components/ui/input';
import FadeContent from '@/components/reactbits/FadeContent';
import {managerDemoEnabled,money} from '@/lib/managerDemoStore';
export {Button,Input,Card,CardContent,money};
export function Screen({title,description,code,action,children}){return <div className="manager-screen"><FadeContent blur={false} duration={350} distance={10} className="manager-motion"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="label text-[#176B3A]">FACILITY WORKSPACE {code&&`· ${code}`}</p><h1 className="mt-2 font-heading text-3xl font-bold tracking-tight md:text-4xl">{title}</h1><p className="mt-3 max-w-3xl text-sm leading-6 text-slate-500">{description}</p></div>{action}</div></FadeContent><p className="manager-demo mt-5">{managerDemoEnabled?'Demo facility · Changes are saved in this browser only. No real approvals, messages, rental activation or payments are performed.':'Manager API is not connected · Live data and actions are unavailable.'}</p><div className="mt-6 space-y-6">{children}</div></div>;}
export function Panel({title,subtitle,children,action}){return <Card><CardContent><div className="mb-5 flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-lg font-bold">{title}</h2>{subtitle&&<p className="mt-1 text-xs leading-5 text-slate-500">{subtitle}</p>}</div>{action}</div>{children}</CardContent></Card>;}
export function Status({value}){const positive=['ACTIVE','VERIFIED','APPROVED','PAID','COMPLETED','RESOLVED','AVAILABLE','CLEAR','IN_STORAGE'].includes(value);const danger=['REJECTED','OVERDUE','HIGH','UNAVAILABLE'].includes(value);return <Badge variant={positive?'green':'orange'} className={danger?'bg-red-50 text-red-700':''}>{String(value||'Unassigned').replaceAll('_',' ')}</Badge>;}
export function Details({values}){return <dl className="grid gap-5 sm:grid-cols-2">{values.map(([label,value])=><div key={label}><dt className="text-xs text-slate-500">{label}</dt><dd className="mt-1 break-words text-sm font-semibold">{value??'—'}</dd></div>)}</dl>;}
export function Table({columns,rows,label='Facility records',empty='No records match your filters.'}){return <div className="manager-table-scroll" tabIndex={0} aria-label={`${label} scroll area`}><table className="manager-table" aria-label={label}><thead><tr>{columns.map(c=><th scope="col" key={c.key}>{c.label}</th>)}</tr></thead><tbody>{rows.map(row=><tr key={row.id}>{columns.map(c=><td key={c.key}>{c.render?c.render(row):row[c.key]??'—'}</td>)}</tr>)}{!rows.length&&<tr><td colSpan={columns.length} className="py-10 text-center text-slate-500">{empty}</td></tr>}</tbody></table></div>;}
export function OpenLink({to,children='View details'}){return <Link className="manager-link inline-flex items-center gap-1 font-semibold" to={to}>{children}<ArrowUpRight size={14}/></Link>;}
export function Field({label,children,hint}){return <label className="manager-field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
export function Select({label,value,onChange,options,disabled=false,required=false}){return <select aria-label={label} value={value} onChange={e=>onChange(e.target.value)} disabled={disabled} required={required}>{options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,String(o).replaceAll('_',' ')];return <option key={v} value={v}>{l}</option>;})}</select>;}
export function Textarea(props){return <textarea className="manager-textarea" {...props}/>;}
export function Filters({children}){return <div className="manager-filters">{children}</div>;}
export function Message({error,success}){return error?<p role="alert" className="rounded-xl bg-red-50 p-4 text-sm text-red-700">{error}</p>:success?<p role="status" className="rounded-xl bg-emerald-50 p-4 text-sm text-emerald-800">{success}</p>:null;}
export function Timeline({entries=[]}){return <ol className="manager-timeline">{entries.map((entry,i)=><li key={i}><span className="text-xs text-slate-500">{new Date(entry.at).toLocaleString('en-GB')}</span><div className="mt-1"><Status value={entry.status}/></div><p className="mt-2 text-sm">{entry.note}</p></li>)}{!entries.length&&<li>No events yet.</li>}</ol>;}
export function Meter({label,used,max,unit='m³'}){const pct=max>0?Math.min(100,used/max*100):0;return <div><div className="mb-2 flex flex-wrap justify-between gap-2 text-sm"><b>{label}</b><span>{used.toFixed(1)} / {max.toFixed(1)} {unit}</span></div><div className="manager-meter" role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={max||100} aria-valuenow={used}><div style={{width:`${pct}%`}}/></div><p className="mt-2 text-xs text-slate-500">{Math.max(0,max-used).toFixed(1)} {unit} remaining · {pct.toFixed(0)}% utilized</p></div>;}
export function NotFound({title='Record unavailable'}){return <Panel title={title} subtitle="The record does not belong to your assigned facility, or is unavailable."><OpenLink to="/manager/dashboard">Back to dashboard</OpenLink></Panel>;}
export function ExportButton(){return <div><Button variant="outline" disabled title="Report export requires a connected Manager API"><Download size={16}/>Export report</Button><p className="mt-2 text-xs text-slate-500">Export API unavailable</p></div>;}
export function Dialog({title,onClose,children}){const ref=useRef(null),id=useId();useEffect(()=>{const dialog=ref.current;dialog.showModal();return()=>dialog.close();},[]);return <dialog ref={ref} aria-labelledby={id} className="manager-dialog experience-theme" onCancel={onClose}><div className="flex items-center justify-between gap-3"><h2 id={id} className="text-xl font-bold">{title}</h2><Button type="button" variant="ghost" size="icon" aria-label="Close dialog" onClick={onClose}><X size={18}/></Button></div><div className="mt-5">{children}</div></dialog>;}
export function Decision({status,allowed,available=true,onDecision}){const [modal,setModal]=useState(null),[reason,setReason]=useState(''),[error,setError]=useState(''),[success,setSuccess]=useState('');function submit(e){e.preventDefault();try{onDecision(modal,reason);setSuccess(`Request ${modal.toLowerCase()} in the demo workspace.`);setModal(null);}catch(err){setError(err.message);}}return <div className="space-y-3"><Message success={success}/>{status==='PENDING'&&<><div className="flex flex-wrap gap-3"><Button disabled={!managerDemoEnabled||!allowed||!available} onClick={()=>{setError('');setModal('APPROVED');}}>Approve</Button><Button variant="outline" disabled={!managerDemoEnabled||!allowed} onClick={()=>{setError('');setModal('REJECTED');}}>Reject</Button></div>{!allowed&&<p className="text-xs text-slate-500">Your role cannot review this request.</p>}</>}{modal&&<Dialog title={modal==='APPROVED'?'Approve request':'Reject request'} onClose={()=>setModal(null)}><form onSubmit={submit} className="space-y-4"><p className="text-sm text-slate-500">This decision changes the local demo record only.</p>{modal==='REJECTED'&&<Field label="Rejection reason"><Textarea aria-label="Rejection reason" required value={reason} onChange={e=>setReason(e.target.value)}/></Field>}<Message error={error}/><Button type="submit" variant={modal==='REJECTED'?'orange':'default'}>Confirm {modal==='APPROVED'?'approval':'rejection'}</Button></form></Dialog>}</div>;}
export function useAction(){const [error,setError]=useState(''),[success,setSuccess]=useState('');return {error,success,run(fn,message='Saved in the demo workspace.'){setError('');setSuccess('');try{fn();setSuccess(message);return true;}catch(err){setError(err.message);return false;}}};}
'''
files['src/layouts/ManagerLayout.jsx']=r'''import {Link,NavLink,Outlet} from 'react-router-dom';
import {LayoutDashboard,CalendarCheck,Users,Warehouse,Layers,ClipboardList,UserCheck,CalendarPlus,Wrench,LifeBuoy,RotateCcw,Receipt,ChartNoAxesCombined,Building2} from 'lucide-react';
import Brand from '@/components/common/Brand';
import {assignedFacility} from '@/mocks/managerData';
import './experience.css';
import './manager.css';
const links=[['dashboard',LayoutDashboard,'Dashboard'],['reservations',CalendarCheck,'Reservations'],['customers',Users,'Customers'],['storage-units',Warehouse,'Storage units'],['storage-locations',Layers,'Storage locations'],['operations',ClipboardList,'Daily operations'],['tasks',UserCheck,'Staff assignment'],['extensions',CalendarPlus,'Extensions'],['maintenance',Wrench,'Maintenance'],['support',LifeBuoy,'Support'],['refunds',RotateCcw,'Refunds'],['charges',Receipt,'Extra charges'],['reports/revenue',ChartNoAxesCombined,'Revenue report'],['reports/utilization',ChartNoAxesCombined,'Utilization report'],['reports/rentals',ChartNoAxesCombined,'Rental report']];
export default function ManagerLayout(){return <div className="experience-theme manager-shell"><header className="manager-topbar"><Link to="/manager/dashboard" aria-label="VaultSpace manager"><Brand/></Link><div className="manager-facility"><Building2 size={17}/><span><b>{assignedFacility.name}</b><small>Assigned facility · {assignedFacility.id}</small></span></div><div className="manager-identity"><span className="manager-avatar">ML</span><span><b>{assignedFacility.manager}</b><small>Facility Manager</small></span></div></header><div className="manager-workspace"><aside className="manager-sidebar"><p className="px-3 pb-3 text-[10px] font-bold uppercase tracking-widest text-[#7A8B7F]">Facility management</p><nav aria-label="Manager navigation">{links.map(([path,Icon,label])=><NavLink key={path} to={`/manager/${path}`}><Icon size={17}/>{label}</NavLink>)}</nav><div className="manager-scope"><Building2 size={18}/><p>One facility.<br/><b>Every detail in view.</b></p><span>Scoped to {assignedFacility.id}</span></div></aside><main className="manager-main"><Outlet/></main></div></div>;}
'''
files['src/layouts/manager.css']=r'''/* Facility Manager-only presentation. Existing Customer/Public styles are preserved. */
.manager-shell{background:#FAFAF7;color:#173D28;min-height:100vh}.manager-topbar{height:82px;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:0 28px;background:#fff;border-bottom:1px solid #e1e8e2;position:sticky;top:0;z-index:30}.manager-facility,.manager-identity{display:flex;align-items:center;gap:12px;font-size:13px}.manager-topbar small{display:block;margin-top:4px;font-size:10px;color:#7a8b7f}.manager-avatar{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;background:#eaf5ee;font-size:12px;font-weight:700}.manager-workspace{display:grid;grid-template-columns:238px minmax(0,1fr)}.manager-sidebar{background:#fff;border-right:1px solid #e1e8e2;padding:26px 16px;position:sticky;top:82px;height:calc(100vh - 82px);overflow:auto}.manager-sidebar nav{display:grid;gap:5px}.manager-sidebar nav a{display:flex;align-items:center;gap:11px;padding:11px 13px;border-radius:10px;font-size:12px;font-weight:600;color:#627168;transition:background .2s,color .2s}.manager-sidebar nav a:hover{background:#f1f7f1}.manager-sidebar nav a.active{background:#176B3A;color:#fff;box-shadow:0 4px 12px #176b3a22}.manager-scope{margin-top:26px;padding:18px;border-radius:14px;background:#eaf5ee;font-size:12px;line-height:1.6}.manager-scope span{display:block;margin-top:10px;color:#768579;font-size:10px}.manager-main{min-width:0}.manager-screen{max-width:1440px;margin:auto;padding:32px}.manager-demo{padding:12px 16px;border:1px solid #e1e8e2;border-radius:10px;background:#f1f6ef;color:#64746a;font-size:11px;line-height:1.7}.manager-shell .grid>*{min-width:0}.manager-table-scroll{max-width:100%;overflow:auto;border:1px solid #e1e8e2;border-radius:12px}.manager-table{border-collapse:collapse;width:100%;min-width:640px;text-align:left;font-size:12px}.manager-table th{background:#f1f6ef;color:#6b7e70;font-size:10px;text-transform:uppercase;letter-spacing:.05em;padding:14px 16px;white-space:nowrap}.manager-table td{padding:17px 16px;border-top:1px solid #e1e8e2;vertical-align:top;line-height:1.8}.manager-table tbody tr:hover{background:#fafcf9}.manager-link{color:#176B3A}.manager-link:hover{text-decoration:underline}.manager-field{display:flex;flex-direction:column;gap:8px;min-width:0;font-size:12px;font-weight:600;color:#526554}.manager-field small{font-weight:400;line-height:1.6;color:#7a8b7f}.manager-shell select,.manager-dialog select{width:100%;height:48px;background:#f1f7f1;border:1px solid #dce7de;border-radius:9px;padding:0 12px;font-size:13px;color:#173D28}.manager-textarea{width:100%;min-height:110px;border:1px solid #dce7de;border-radius:9px;background:#f1f7f1;padding:12px 16px;font-weight:400;font-size:13px;resize:vertical}.manager-shell :is(select,textarea):focus-visible,.manager-dialog :is(select,textarea):focus-visible{outline:2px solid #176B3A;outline-offset:2px}.manager-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px;margin-bottom:22px}.manager-meter{height:8px;background:#eaf0e8;border-radius:8px;overflow:hidden}.manager-meter>div{height:100%;background:#176B3A;border-radius:8px;transition:width .35s}.manager-timeline{border-left:2px solid #e1e8e2;padding-left:22px;display:grid;gap:24px;margin-left:6px}.manager-timeline li{position:relative}.manager-timeline li:before{content:'';position:absolute;left:-28px;top:4px;width:10px;height:10px;background:#f28c28;border:2px solid white;box-shadow:0 0 0 2px #eaf5ee;border-radius:50%}.manager-dialog{width:calc(100% - 32px);max-width:520px;border:1px solid #dce7de;border-radius:18px;padding:26px;box-shadow:0 30px 100px #173d2840;color:#173D28}.manager-dialog::backdrop{background:#173d2866;backdrop-filter:blur(3px)}.manager-kpi{position:relative;overflow:hidden}.manager-kpi .kpi-icon{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:#eaf5ee;color:#176B3A}.manager-kpi:nth-child(2n) .kpi-icon{background:#fff1e3;color:#d87517}.manager-board{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.manager-board-column{padding:16px;background:#f1f6ef;border:1px solid #e1e8e2;border-radius:16px}.manager-task-card{padding:16px;margin-top:14px;border:1px solid #e1e8e2;background:#fff;border-radius:12px}.manager-callout{background:linear-gradient(115deg,#176B3A,#24583a);color:white;border-radius:18px;padding:26px}.manager-callout p{color:#d9e9dc}.manager-shell .manager-callout a{background:#f28c28;color:#fff}.manager-chart{display:grid;gap:18px}.manager-chart-row{display:grid;grid-template-columns:80px minmax(0,1fr) 130px;align-items:center;gap:12px;font-size:12px}.manager-chart-track{height:24px;border-radius:6px;background:#eaf5ee;overflow:hidden}.manager-chart-track>div{height:100%;background:#176b3a;border-radius:6px}.manager-shell :is(input,select,textarea):disabled{opacity:.6;cursor:not-allowed}.manager-crumbs{display:flex;flex-wrap:wrap;gap:8px;font-size:12px;color:#6b7e70}.manager-crumbs a{color:#176B3A;text-decoration:underline}
@media(max-width:1100px){.manager-workspace{grid-template-columns:205px minmax(0,1fr)}.manager-screen{padding:24px}.manager-facility{display:none}.manager-board{grid-template-columns:1fr}}
@media(max-width:760px){.manager-topbar{height:70px;padding:0 16px}.manager-identity>span:last-child{display:none}.manager-workspace{display:block}.manager-sidebar{position:sticky;top:70px;height:auto;padding:10px 12px;border-right:none;border-bottom:1px solid #e1e8e2;z-index:25}.manager-sidebar>p,.manager-scope{display:none}.manager-sidebar nav{display:flex;overflow:auto;gap:6px}.manager-sidebar nav a{white-space:nowrap;padding:10px 12px;font-size:11px}.manager-screen{padding:24px 16px}.manager-chart-row{grid-template-columns:65px minmax(0,1fr) 95px}.manager-table{font-size:11px}.manager-table td,.manager-table th{padding:12px}.manager-screen h1{font-size:28px}}
@media(prefers-reduced-motion:reduce){.manager-motion{opacity:1!important;transform:none!important;filter:none!important;transition:none!important}.manager-shell *{scroll-behavior:auto;transition:none!important}}
'''
for name,content in files.items():
 p=Path(name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
